const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let wrangler;
try { wrangler = require("wrangler"); } catch (e) { broken("could not load wrangler: " + e.message); }
fs.mkdirSync("/tmp/proj", { recursive: true });
fs.writeFileSync("/tmp/proj/wrangler.json", JSON.stringify({
  name: "flagship-test",
  compatibility_date: "2025-01-01",
  flagship: [
    { binding: "FLAGS", app_id: "local-app" },
    { binding: "REMOTE_FLAGS", app_id: "remote-app", remote: true }
  ]
}));
const conn = new URL("http://127.0.0.1:9/");
let out;
try {
  out = wrangler.unstable_getMiniflareWorkerOptions("/tmp/proj/wrangler.json", undefined, { remoteProxyConnectionString: conn });
} catch (e) { broken("unstable_getMiniflareWorkerOptions threw: " + e.message); }
const fl = out && out.workerOptions && out.workerOptions.flagship;
if (!fl || !fl.FLAGS || !fl.REMOTE_FLAGS) broken("flagship bindings missing from worker options: " + JSON.stringify(fl));
if (!fl.REMOTE_FLAGS.remoteProxyConnectionString) broken("binding with remote: true was not sent to the remote proxy");
if (fl.FLAGS.remoteProxyConnectionString) symptom("flagship binding without remote: true is sent to the remote proxy instead of the local store");
console.log("OK: flagship binding without remote: true stays local; remote: true goes remote");
process.exit(0);

